public enum State { Idle, Connecting, Running, Error }

void Handle(Event input)
{
    _state = (_state, input) switch
    {
        (State.Idle, Event.Start) => State.Connecting,
        (State.Connecting, Event.Connected) => State.Running,
        (_, Event.Fail) => State.Error,
        (State.Error, Event.Reset) => State.Idle,
        _ => _state,
    };
}

public sealed class Pid(double kp, double ki, double kd)
{
    private double _integral;
    private double _previousError;

    public double Update(double setpoint, double measured, double dt)
    {
        double error = setpoint - measured;
        _integral += error * dt;
        double derivative = (error - _previousError) / dt;
        _previousError = error;
        return kp * error + ki * _integral + kd * derivative;
    }
}

